import unittest

from hourglass.models import Span
from hourglass.parsing import parse_span
from hourglass.rounding import round_labels, snap_minute


class SnapTests(unittest.TestCase):
    def test_nearest_step(self):
        self.assertEqual(snap_minute(7, 15), 0)
        self.assertEqual(snap_minute(8, 15), 15)

    def test_halves_round_up(self):
        self.assertEqual(snap_minute(5, 10), 10)


class LabelTests(unittest.TestCase):
    def test_label_format(self):
        spans = [parse_span("09:02-17:11")]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_one_label_per_span(self):
        spans = [Span(0, 60), Span(100, 200)]
        labels = round_labels(spans, 30)
        self.assertEqual(
            labels,
            ["00:00-01:00 (1h 0m)", "01:30-03:30 (2h 0m)"]
        )

    def test_end_of_day(self):
        spans = [parse_span("23:20-24:00")]
        labels = round_labels(spans, 60)
        self.assertEqual(labels, ["23:00-24:00 (1h 0m)"])

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])


class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45, 90, 2.5):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)

    def test_good_steps_work(self):
        for step in (1, 5, 10, 15, 20, 30, 60):
            labels = round_labels([Span(0, 120)], step)
            self.assertEqual(len(labels), 1)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_labels([Span(61, 65)], 15)


if __name__ == "__main__":
    unittest.main()
